29: /**
30:  * HarnessAgent 构建与缓存。
31:  *
32:  * <p>模型切换时重建 Agent；会话状态保存在独立的 agentStateStore 中，
33:  * 因此不会因 Agent 实例替换而丢失。</p>
34:  */
35: @Slf4j
36: @Component
37: @RequiredArgsConstructor
38: public class AgentFactory {
39: 
40:     private final ModelHolder modelHolder;
41:     private final ToolRegistry toolRegistry;
42:     private final AgentStorageProperties storageProperties;
43:     private final AgentStateStore agentStateStore;
44:     private final TaskRepository subagentTaskRepository;
45:     private final MessageBus subagentMessageBus;
46:     private final SubagentCatalog subagentCatalog;
47:     private final TokenUsageMiddleware tokenUsageMiddleware;
48:     private final ContextInjectionMiddleware contextInjectionMiddleware;
49:     private final ToolSchemaSelectionMiddleware toolSchemaSelectionMiddleware;
50:     private final SessionCatalogService sessionCatalogService;
51:     private final ProjectRegistry projectRegistry;
52: 
53:     /** 按会话与项目根隔离 Agent，避免会话之间互相修改 Toolkit 的可变激活分组。 */
54:     private final Map<AgentCacheKey, HarnessAgent> cachedAgents = new HashMap<>();
55: 
56:     /** 项目根变化时重建文件系统能力；无绑定会话的兼容入口独占一个缓存项。 */
57:     private record AgentCacheKey(String sessionId, Path projectRoot) {}
58: 
59:     /**
60:      * 用对象引用识别 ModelHolder 是否已经切换了模型实例。
61:      */
62:     private volatile Model cachedModel;
63: 
64:     /** 返回不绑定项目的通用 Agent，主要用于兼容与测试。 */
65:     public synchronized HarnessAgent currentAgent() {
66:         return currentAgent(null);
67:     }
68: 
69:     /** 按会话身份与解析后的项目根返回独享 Toolkit 的 Agent。 */
70:     public synchronized HarnessAgent currentAgent(String sessionId) {
71:         Model currentModel = modelHolder.getModel();
72:         if (cachedModel != currentModel) {
73:             cachedAgents.values().forEach(this::closeQuietly);
74:             cachedAgents.clear();
75:             cachedModel = currentModel;
76:         }
77: 
78:         Path projectRoot = resolveProjectRoot(sessionId);
79:         AgentCacheKey cacheKey = new AgentCacheKey(
80:                 sessionId == null || sessionId.isBlank() ? null : sessionId, projectRoot);
81:         return cachedAgents.computeIfAbsent(cacheKey, ignored -> createHarnessAgent(currentModel, projectRoot));
82:     }
83: 
84:     /** 构建 Agent 时只指定根目录和状态存储，不拼接任何 sessionDir。 */
85:     private HarnessAgent createHarnessAgent(Model model, Path projectRoot) {
86:         // 模型名缺失时给兜底名，保证系统提示词可读
87:         String modelName = model.getModelName() == null ? "unknown-model" : model.getModelName();
88:         // 项目会话使用不含日常聊天模块的工程提示词；普通会话保留聊天、语言与判断规则
89:         String systemPrompt = projectRoot == null
90:                 ? PromptBuilder.buildDefaultSystemPrompt(modelName, System.getProperty("user.dir"))
91:                 : PromptBuilder.buildProjectSystemPrompt(modelName, projectRoot.toString());
92:         // 组装 HarnessAgent：计划模式、工具集、权限、工作区、状态存储、上下文压缩
93:         HarnessAgent.Builder builder = HarnessAgent.builder()
94:                 .name("butvan_agent")
95:                 .sysPrompt(systemPrompt)
96:                 .model(model)
97:                 .maxIters(25)
98:                 .middleware(new butvan.agent.agents.prompts.RuntimeDateMiddleware())
99:                 .middleware(contextInjectionMiddleware) // 先向消息列表临时注入有界个人上下文
100:                 .middleware(toolSchemaSelectionMiddleware)
101:                 .middleware(tokenUsageMiddleware)
102:                 .enablePlanMode() // 开启计划模式
103:                 .planFileDirectory("plans")
104:                 .toolkit(toolRegistry.getToolkit())
105:                 .workspace(storageProperties.getWorkspaceDirectory())
106:                 .disableWorkspaceContext()
107:                 // 同时传播到框架子Agent，防止其重新注册本地Markdown记忆工具。
108:                 .disableMemoryTools()
109:                 // 自动经历仅走应用授权 seam；关闭框架整段抽取、合并与维护写入。
110:                 .disableMemoryHooks()
111:                 // 框架自动恢复发生在 ConfirmResult 消费之前，会误伤正常 HITL；遗留调用由应用层恢复。
112:                 .enablePendingToolRecovery(false)
113:                 .stateStore(agentStateStore)
114:                 .taskRepository(subagentTaskRepository)
115:                 .messageBus(subagentMessageBus)
116:                 .subagents(subagentCatalog.declarations())
117:                 .compaction(CompactionConfig.builder()
118:                         .flushBeforeCompact(false)
119:                         .triggerMessages(30)    // 30 条消息触发上下文压缩
120:                         .keepMessages(10)       // 压缩后保留最近 10 条
121:                         //.triggerTokens(131072)   // 固定 token 阈值，禁用动态 contextWindowSize 探测（避免框架向 DashScope 发送非法 URL 的探测请求）
122:                         .build());
123:         if (projectRoot != null) {
124:             builder.filesystem(new LocalFilesystemSpec()
125:                     .project(projectRoot)
126:                     .projectWritable(true)
127:                     .mode(LocalFsMode.ROOTED));
128:         }
129:         HarnessAgent agent = builder.build();
130:         toolRegistry.enableOnDemandSchemas(agent.getToolkit());
131:         return agent;
132:     }
133: 
134:     private Path resolveProjectRoot(String sessionId) {
135:         if (sessionId == null || sessionId.isBlank()) return null;
136:         String projectId = sessionCatalogService.requireActive(sessionId).projectId();
137:         if (projectId == null || projectId.isBlank()) return null;
138:         return Path.of(projectRegistry.resolve(projectId).rootPath());
139:     }
140: 
141:     private void closeQuietly(HarnessAgent agent) {
142:         try {
143:             agent.close();
144:         } catch (Exception e) {
145:             // 模型切换时旧 Agent 已不可再用，关闭失败不阻断新 Agent 创建。
146:             log.debug("模型切换时关闭旧 Agent 失败", e);
147:         }
148:     }
149: }

