25: @Slf4j
26: public class PermissionChecker {
27: 
28:     /** 当前系统的运行权限模式 */
29:     @Getter
30:     private PermissionMode mode;
31: 
32:     /** 当前项目根路径 */
33:     private final Path projectRoot;
34: 
35:     /** 从 YAML 解析装载的 AgentScope 原生权限规则列表 */
