63:      * 从本地用户配置路径装载三层 YAML 权限规则。
64:      *
65:      * @return 解析完成的 PermissionRule 规则列表
66:      */
67:     private List<PermissionRule> loadRules() {
68:         List<PermissionRule> rules = new ArrayList<>();
69: 
70:         // 默认用户配置文件路径: ~/.butvan-agent/permissions.yaml
71:         Path userConfigPath = Paths.get(System.getProperty("user.home"), ".butvan-agent", "permissions.yaml");
72: 
73:         if (Files.exists(userConfigPath)) {
74:             log.info("[PermissionChecker] 检测到本地权限配置文件: {}", userConfigPath);
75:             rules.addAll(parseYamlRules(userConfigPath));
76:         } else {
77:             log.debug("[PermissionChecker] 未检测到本地权限配置文件，将使用默认内置规则。");
78:         }
79: 
